    /** Puja and chadhava titles. */
    private function rituals(): array
    {
        $grah = ['surya' => 'सूर्य', 'chandra' => 'चंद्र', 'mangal' => 'मंगल', 'budh' => 'बुध', 'guru' => 'गुरु', 'shukra' => 'शुक्र', 'shani' => 'शनि', 'rahu' => 'राहु', 'ketu' => 'केतु'];
        $lagna = ['mesh' => 'मेष', 'vrishabh' => 'वृषभ', 'mithun' => 'मिथुन', 'kark' => 'कर्क', 'simha' => 'सिंह', 'kanya' => 'कन्या', 'tula' => 'तुला', 'vrishchik' => 'वृश्चिक', 'dhanu' => 'धनु', 'makar' => 'मकर', 'kumbh' => 'कुंभ', 'meen' => 'मीन'];
        $out = ['navgrah-shanti-puja' => 'नवग्रह शांति पूजा'];
        foreach ($grah as $k => $h) {
            $out["$k-grah-shanti-puja"] = "$h ग्रह शांति पूजा";
        }
        foreach ($lagna as $k => $h) {
            $out["$k-lagna-puja"] = "$h लग्न पूजा";
        }

        return $out + [
            'mahamrityunjay-puja' => 'महामृत्युंजय पूजा', 'rudrabhishek' => 'रुद्राभिषेक', 'pitra-dosh-nivaran-puja' => 'पितृ दोष निवारण पूजा', 'kaal-sarp-dosh-nivaran-puja' => 'काल सर्प दोष निवारण पूजा',
            'kaal-bhairav-puja' => 'काल भैरव पूजा', 'maa-baglamukhi-puja' => 'माँ बगलामुखी पूजा', 'rin-mukti-puja' => 'ऋण मुक्ति पूजा', 'vivah-siddhi-puja' => 'विवाह सिद्धि पूजा',
            'uma-maheshwar-puja' => 'उमा महेश्वर पूजा', 'parivar-sukh-samriddhi-puja' => 'परिवार सुख समृद्धि पूजा', 'santan-badha-puja' => 'संतान बाधा पूजा', 'sarva-karya-siddhi-puja' => 'सर्व कार्य सिद्धि पूजा',
            'shatru-badha-nazar-dosh-puja' => 'शत्रु बाधा / नज़र दोष पूजा', 'nasha-mukti-prarthana' => 'नशा मुक्ति प्रार्थना', 'videsh-yatra-siddhi-yagya' => 'विदेश यात्रा सिद्धि यज्ञ',
            'dhan-lakshmi-ganesh-puja' => 'धन लक्ष्मी गणेश पूजा', 'maha-lakshmi-puja' => 'महालक्ष्मी पूजा', 'dhan-lakshmi-navratri-anushthan' => 'धन लक्ष्मी नवरात्रि अनुष्ठान', 'durga-ashtami-puja' => 'दुर्गा अष्टमी पूजा',
            'dev-diwali-sarva-devta-puja' => 'देव दीपावली सर्व देवता पूजा', 'maha-gayatri-jaap-and-tulsi-vivah' => 'महा गायत्री जप और तुलसी विवाह', 'shiv-gauri-puja-karwa-chauth' => 'शिव गौरी पूजा (करवा चौथ)',
