    /** Hindi option name for a seeded English variant name, or null. */
    public static function variantName(string $en): ?string
    {
        $exact = [
            'One question — written answer' => 'एक प्रश्न — लिखित उत्तर', 'Two questions — written answers' => 'दो प्रश्न — लिखित उत्तर', 'Three questions — written answers' => 'तीन प्रश्न — लिखित उत्तर',
            'Single — sankalp for 1 person' => 'एकल — 1 व्यक्ति का संकल्प', 'Couple — sankalp for 2 people' => 'दंपती — 2 लोगों का संकल्प', 'Family — sankalp for up to 6 members' => 'परिवार — 6 सदस्यों तक का संकल्प',
            'Standard' => 'सामान्य', 'PDF report' => 'पीडीएफ रिपोर्ट', 'Bundle' => 'बंडल', 'Package' => 'पैकेज', 'Written report (both palms)' => 'लिखित रिपोर्ट (दोनों हथेलियाँ)',
            'Online review of floor plan' => 'नक्शे की ऑनलाइन समीक्षा', 'On-site visit (Patna)' => 'स्थल निरीक्षण (पटना)',
            'At your home or office (Patna)' => 'आपके घर या कार्यालय में (पटना)', 'At a temple (arranged with you)' => 'मंदिर में (आपसे तय करके)',
            'In person at Patna office' => 'पटना कार्यालय में आमने-सामने', 'Video call' => 'वीडियो कॉल', 'Audio call' => 'ऑडियो कॉल',
        ];
        if (isset($exact[$en])) {
            return $exact[$en];
        }
        $map = ['In person (Patna)' => 'आमने-सामने (पटना)', 'in person' => 'आमने-सामने', 'Audio call' => 'ऑडियो कॉल', 'Video call' => 'वीडियो कॉल', 'video call' => 'वीडियो कॉल',
            'Audio' => 'ऑडियो', 'Video' => 'वीडियो', 'audio' => 'ऑडियो', 'video' => 'वीडियो', 'Chat' => 'चैट', 'Couple' => 'दंपती', 'Urgent' => 'अर्जेंट', '1 hour' => '1 घंटा', ' min' => ' मिनट'];
        $hi = strtr($en, $map);

        return $hi !== $en && ! preg_match('/[A-Za-z]{3,}/', $hi) ? $hi : null;
    }

    public function run(): void
    {
        foreach (self::FAMILIES as $code => [$name, $summary]) {
            $f = ServiceFamily::where('code', $code)->first();
            if ($f && empty($f->translations['hi'])) {
                $f->forceFill(['translations' => ($f->translations ?? []) + ['hi' => ['name' => $name, 'summary' => $summary]]])->save();
            }
        }
        $texts = $this->services();
        foreach ($this->rituals() as $slug => $title) {
            $family = str_ends_with($slug, 'chadhava') ? 'chadhava' : 'puja';
            $texts[$slug] = [$title, $family === 'puja' ? "$title — अधिकृत पुजारी या मंदिर द्वारा आपके नाम और गोत्र से संकल्प के साथ।" : "$title — मंदिर में आपकी ओर से अर्पण।",
                null, $family === 'puja' ? ['आपके नाम और गोत्र से संकल्प (एकल: 1 व्यक्ति, दंपती: 2, परिवार: 6 सदस्यों तक)', 'तय तारीख पर अधिकृत पुजारी या मंदिर द्वारा पूरी विधि और मंत्र से पूजा',
                    'तारीख, समय और स्थिति की जानकारी आपके खाते, ईमेल और ऐप सूचना में; हमारी टीम व्हाट्सऐप पर भी संदेश देती है', 'पूजा की फोटो आपके खाते में, और जहाँ मंदिर अनुमति दे वहाँ वीडियो लिंक', 'परिवार पैकेज के साथ भारत में कूरियर से प्रसाद']
                    : ['आपके नाम और गोत्र से मंदिर में अर्पण', 'तारीख और स्थिति की जानकारी आपके खाते, ईमेल और ऐप सूचना में', 'अर्पण की फोटो आपके खाते में'],
                null, $family === 'puja' ? self::PUJA_NOTE : 'अर्पण एक आध्यात्मिक साधना है और इससे किसी परिणाम की गारंटी नहीं है।'];
        }
        foreach ($texts as $slug => $t) {
            $o = Offering::where('slug', $slug)->first();
            if (! $o || $o->translations()->where('locale', 'hi')->exists()) {
                continue;
            }
            $o->translations()->create(['locale' => 'hi', 'title' => $t[0], 'summary' => $t[1], 'body' => $t[2] ?? null, 'includes' => $t[3] ?? null,
                'audience' => $t[4] ?? null, 'disclaimer' => $t[5] ?? null, 'meta_description' => $t[1]]);
        }
        foreach (OfferingVariant::all() as $v) {
            if (empty($v->translations['hi']) && ($hi = self::variantName($v->name))) {
                $v->forceFill(['translations' => ($v->translations ?? []) + ['hi' => ['name' => $hi]]])->save();
            }
        }
        if (DB::table('faqs')->where('locale', 'hi')->count() === 0) {
            $faqs = [
                ['परामर्श कैसे बुक करें?', 'सेवा चुनकर बुकिंग अनुरोध भेजें, +91-9835258203 पर कॉल करें या व्हाट्सऐप करें। परामर्श कंकड़बाग, पटना में आमने-सामने और वीडियो या ऑडियो कॉल से ऑनलाइन उपलब्ध है।'],
